-- Transaction-only contract test. No notification or upload is committed.
begin;
do $$
declare admin_id uuid; athlete uuid; outsider uuid; request uuid:=gen_random_uuid(); path text; badpath text;
 files jsonb; n integer; denied boolean; affected integer;
begin
 select id into admin_id from public.profiles where role='admin' limit 1;
 select p.id into athlete from public.profiles p where p.role='student' and not exists(select 1 from public.academy_student_status s where s.student_id=p.id and not s.active) limit 1;
 select id into outsider from public.profiles where role='teacher' limit 1;
 assert admin_id is not null and athlete is not null and outsider is not null,'Test actors unavailable';
 path:=admin_id::text||'/'||gen_random_uuid()::text||'.pdf';badpath:=admin_id::text||'/'||gen_random_uuid()::text||'.pdf';
 insert into storage.objects(bucket_id,name,owner_id,metadata) values('academy-notification-files',path,admin_id::text,'{"size":128,"mimetype":"application/pdf"}'),('academy-notification-files',badpath,admin_id::text,'{"size":20971521,"mimetype":"application/pdf"}');
 files:=jsonb_build_array(jsonb_build_object('path',path,'name','Antrenman.pdf','size',1,'mime','image/png'));
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 set local role authenticated;
 assert barida_messages.can_read_file(path),'Uploader cannot read own draft';
 assert barida_messages.can_delete_file(path),'Uploader cannot remove unsent draft';
 n:=public.academy_send_notification_files(request,'individual','Attachment verification','Files contract test',files,athlete);
 assert n=1,'Incorrect recipient count';
 n:=public.academy_send_notification_files(request,'individual','Attachment verification','Files contract test',files,athlete);
 assert n=1,'Retry changed result';
 assert not barida_messages.can_delete_file(path),'Shared attachment can be deleted';
 denied:=false;begin perform public.academy_send_notification_files(request,'individual','Different payload','Files contract test',files,athlete);exception when others then denied:=true;end;assert denied,'Retry accepted changed payload';
 denied:=false;begin perform public.academy_send_notification_files(gen_random_uuid(),'individual','Oversize','Files test',jsonb_build_array(jsonb_build_object('path',badpath,'name','oversize.pdf')),athlete);exception when others then denied:=true;end;assert denied,'Oversize file accepted';
 denied:=false;begin perform public.academy_send_notification_files(gen_random_uuid(),'individual','Wrong owner','Files test',jsonb_build_array(jsonb_build_object('path',outsider::text||'/'||gen_random_uuid()::text||'.pdf','name','wrong.pdf')),athlete);exception when others then denied:=true;end;assert denied,'Foreign upload accepted';
 reset role;
 assert (select count(*) from public.academy_notifications where attachments @> jsonb_build_array(jsonb_build_object('path',path)))=1,'Retry duplicated notification';
 assert (select attachments->0->>'mime' from public.academy_notifications where attachments @> jsonb_build_array(jsonb_build_object('path',path)))='application/pdf','Client forged MIME metadata';
 assert (select (attachments->0->>'size')::integer from public.academy_notifications where attachments @> jsonb_build_array(jsonb_build_object('path',path)))=128,'Client forged file size';
 perform set_config('request.jwt.claim.sub',athlete::text,true);
 set local role authenticated;
 assert (select count(*) from storage.objects where bucket_id='academy-notification-files' and name=path)=1,'Recipient cannot read attachment';
 denied:=false;begin update public.academy_notifications set attachments='[]' where recipient_id=athlete;exception when insufficient_privilege then denied:=true;end;assert denied,'Recipient may edit attachment references';
 update storage.objects set metadata='{}' where bucket_id='academy-notification-files' and name=path;get diagnostics affected=row_count;assert affected=0,'Recipient replaced the file';
 reset role;
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 set local role authenticated;
 assert (select count(*) from storage.objects where bucket_id='academy-notification-files' and name=path)=0,'Unrelated user can read attachment';
 assert not barida_messages.can_read_file(path),'Unrelated user may sign private URL';
 denied:=false;begin perform public.academy_send_notification_files(gen_random_uuid(),'individual','Not admin','Files test',files,athlete);exception when others then denied:=true;end;assert denied,'Non-admin sent an attachment';
 reset role;
 assert not has_function_privilege('anon','public.academy_send_notification_files(uuid,text,text,text,jsonb,uuid,uuid,text)','execute'),'Anonymous send RPC exposed';
 assert (select public=false and file_size_limit=20971520 from storage.buckets where id='academy-notification-files'),'Private bucket contract failed';
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 insert into public.teacher_students(teacher_id,student_id,class_name) values(outsider,athlete,'FILE_ATTACHMENT_TEST') on conflict(teacher_id,student_id) do update set class_name=excluded.class_name;
 set local role authenticated;
 n:=public.academy_send_notification_files(gen_random_uuid(),'class','Class attachment','Class contract test',files,null,outsider,'FILE_ATTACHMENT_TEST');assert n>=1,'Class attachment delivery failed';
 n:=public.academy_send_notification_files(gen_random_uuid(),'all','Ödeme bilgisi','Only management receives this file',files);assert n>=1,'Management-only attachment delivery failed';
 reset role;
 assert not exists(select 1 from public.academy_notifications n join public.profiles p on p.id=n.recipient_id where n.category='payment' and n.attachments @> jsonb_build_array(jsonb_build_object('path',path)) and p.role<>'admin'),'Payment attachment escaped management scope';
end $$;
select 'PASS: private recipient access, sender ownership, immutable shared files, 20 MB limit, authoritative metadata and idempotent sending' as verification;
rollback;
